pub fn advance_line_prefix_indent_only(previous: bool, code_points: Rc<Vec<i64>>) -> bool {
    code_points
        .clone()
        .iter()
        .cloned()
        .fold(previous.clone(), |acc: bool, cp: i64| {
            if code_point_is_line_feed(cp.clone()) {
                true
            } else {
                (acc && code_point_is_indent(cp.clone()))
            }
        })
}

pub fn advance_line_prefix_indent_only_text(previous: bool, lexeme: String) -> bool {
    advance_line_prefix_indent_only(
        previous.clone(),
        Rc::new(lexeme.clone().chars().map(|c| c as i64).collect::<Vec<_>>()),
    )
}

pub fn placement_from_line_prefix(indent_only: bool) -> AnnotationPlacement {
    if indent_only.clone() {
        AnnotationPlacement::LeadingAfterLineIndent
    } else {
        AnnotationPlacement::TrailingAfterSemanticToken
    }
}

